#include <iostream>
#include <sstream>
#include <string>
#include <cctype>
using namespace std;

bool isValidIPv4(const string& ip) {
    if (ip.empty() || ip.back() == '.') return false;
    stringstream ss(ip);
    string part;
    int count = 0;
    while (getline(ss, part, '.')) {
        if (part.empty() || part.size() > 3) return false;
        for (char c : part) if (!isdigit(c)) return false;
        if (part.size() > 1 && part[0] == '0') return false;   // no leading zeros
        if (stoi(part) > 255) return false;
        count++;
    }
    return count == 4;
}

int main() {
    string tests[] = {"192.168.1.10", "256.1.1.1", "10.0.0", "172.16.abc.1",
"01.2.3.4", "127.0.0.1"};
    for (const string& t : tests)
        cout << t << " -> " << (isValidIPv4(t) ? "valid" : "invalid") <<
endl;
    return 0;
}

string ipClass(const string& ip) {
    int first = stoi(ip.substr(0, ip.find('.')));
    if (first >= 1   && first <= 126) return "A";
    if (first == 127)                  return "Loopback";
    if (first >= 128 && first <= 191) return "B";
    if (first >= 192 && first <= 223) return "C";
    if (first >= 224 && first <= 239) return "D (multicast)";
    if (first >= 240 && first <= 255) return "E (reserved)";
    return "Invalid";
}
// ipClass("10.5.2.1") -> A,  ipClass("172.16.0.5") -> B,
ipClass("192.168.1.10") -> C

#include <iostream>
#include <string>
using namespace std;

int main() {
    string url = "https://www.example.in/results/class12?roll=123";
    string protocol, domain, path = "/", query;

    size_t p = url.find("://");
    protocol = url.substr(0, p);
    string rest = url.substr(p + 3);              // www.example.in/results/class12?roll=123

    size_t q = rest.find('?');
    if (q != string::npos) { query = rest.substr(q + 1); rest =
rest.substr(0, q); }

    size_t s = rest.find('/');
    if (s != string::npos) { domain = rest.substr(0, s); path =
rest.substr(s); }
    else domain = rest;

    cout << "Protocol: " << protocol << endl;
    cout << "Domain  : " << domain << endl;
    cout << "Path    : " << path << endl;
    cout << "Query   : " << (query.empty() ? "(none)" : query) << endl;
    cout << "TLD     : " << domain.substr(domain.rfind('.') + 1) << endl;
    return 0;
}

#include <iostream>
#include <sstream>
#include <bitset>
using namespace std;

int main() {
    string ip = "192.168.1.10", part;
    stringstream ss(ip);
    string binary;
    while (getline(ss, part, '.')) {
        if (!binary.empty()) binary += ".";
        binary += bitset<8>(stoi(part)).to_string();    // 8 bits per octet
    }
    cout << ip << " = " << binary << endl;
    return 0;
}
